WITH metrics AS (SELECT id, full_name, dept_id, job_title, hire_date, is_remote, SUM(salary) OVER (PARTITION BY dept_id ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_salary, AVG(salary) OVER (PARTITION BY dept_id ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_salary, MAX(salary) OVER (PARTITION BY dept_id ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_salary, COUNT(salary) OVER (PARTITION BY dept_id ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_salary FROM employees) SELECT id, full_name, hire_date, running_avg_salary, running_max_salary FROM metrics ORDER BY id, running_max_salary
